def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_def = 0
    opp_def = 0
    for a, b in history:
        if a == 'D':
            my_def += 1
        if b == 'D':
            opp_def += 1

    if opp_def > n * 0.8:
        return 'D'

    test_def = 0
    test_ret = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and (i == 0 or history[i-1][0] == 'C'):
            test_def += 1
            if history[i+1][1] == 'D':
                test_ret += 1

    if test_def > 0 and test_ret / test_def >= 0.5:
        recent_opp_def = sum(1 for a, b in history[-3:] if b == 'D')
        if recent_opp_def >= 2:
            return 'D'
        return 'C'

    opp_coop_rate = (n - opp_def) / n
    last_my, last_opp = history[-1]

    if opp_coop_rate > 0.8:
        if last_opp == 'D':
            return 'D'
        if my_def < n // 10 and last_my == 'C':
            return 'D'
        return 'C'

    if opp_coop_rate > 0.5:
        if last_opp == 'D':
            return 'D'
        if last_my == 'D':
            return 'C'
        if my_def < n // 10 and n % 7 == 0:
            return 'D'
        return 'C'

    if last_opp == 'D':
        return 'D'
    if last_my == 'D':
        return 'C' if rng.random() < 0.2 else 'D'
    return 'D'
